import {
    Close as CloseIcon,
    Build as ToolIcon
} from '@mui/icons-material';
import {
    Box,
    Button,
    Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControl,
    FormControlLabel,
    IconButton,
    InputLabel,
    MenuItem,
    Select,
    Typography
} from '@mui/material';
import React from 'react';
import { ToolLibrary } from '../data/Common/ToolLibrary';
import { ConfigurationData } from '../data/ConfigurationData';
import { MachineData } from '../data/Machine/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import { UserMessageQueue } from '../data/UserMessageQueue';
import { IMachineCallback } from '../machine/IMachineCallback';
import { Machine } from '../machine/Machine';
import { LogCategory, Logger } from '../utils/Logger';

interface MeasureToolsDialogProps {
    open: boolean;
    onClose: () => void;
    callback?: IMachineCallback;
}

/**
 * MeasureToolsDialog allows user to select which ATC tools to measure
 * Shows only ATC slots with assigned tool numbers
 * Includes dropdown to confirm currently loaded tool
 */
export function MeasureToolsDialog({ open, onClose, callback }: MeasureToolsDialogProps) {
    const config = ConfigurationData.Instance;
    const machineData = MachineData.Instance;
    const machineState = MachineStateData.Instance;
    const toolLibrary = ToolLibrary.Instance;

    // Get ATC slots with assigned tools that actually exist in the tool library
    const atcToolsWithNumbers = machineData.atcToolClamps
        .filter(slot => {
            // Must have a tool number assigned
            if (slot.clampNumber === null || slot.clampNumber === 0) {
                return false;
            }
            // Must have an actual tool in the library with that number
            const tool = toolLibrary.getToolByNumber(slot.clampNumber);
            return tool !== null && tool !== undefined;
        })
        .map(slot => {
            const tool = toolLibrary.getToolByNumber(slot.clampNumber);
            if (!tool) {
                // This shouldn't happen due to filter above, but be defensive
                return null;
            }
            return {
                toolNumber: slot.clampNumber!,
                toolName: tool.displayName,
                clampNumber: slot.clampNumber!
            };
        })
        .filter((item): item is NonNullable<typeof item> => item !== null)
        .sort((a, b) => a.toolNumber - b.toolNumber);

    // State for which tools are selected for measurement (all checked by default)
    const [selectedTools, setSelectedTools] = React.useState<Set<number>>(() => {
        return new Set(atcToolsWithNumbers.map(t => t.toolNumber));
    });

    // State for currently loaded tool confirmation
    const [currentToolNumber, setCurrentToolNumber] = React.useState<number | null>(
        machineState.currentToolNumber
    );

    // Reset state when dialog opens
    React.useEffect(() => {
        if (open) {
            setSelectedTools(new Set(atcToolsWithNumbers.map(t => t.toolNumber)));
            setCurrentToolNumber(machineState.currentToolNumber);
        }
    }, [open, atcToolsWithNumbers, machineState.currentToolNumber]);

    const handleToggleTool = (toolNumber: number) => {
        const newSelected = new Set(selectedTools);
        if (newSelected.has(toolNumber)) {
            newSelected.delete(toolNumber);
        } else {
            newSelected.add(toolNumber);
        }
        setSelectedTools(newSelected);
    };

    const handleSelectAll = () => {
        setSelectedTools(new Set(atcToolsWithNumbers.map(t => t.toolNumber)));
    };

    const handleDeselectAll = () => {
        setSelectedTools(new Set());
    };

    const handleMeasure = async () => {
        try {
            // Update current tool if changed
            if (currentToolNumber !== machineState.currentToolNumber) {
                machineState.currentToolNumber = currentToolNumber ?? 0;
                await machineState.manualSave();
            }

            const toolsToMeasure = Array.from(selectedTools);

            if (toolsToMeasure.length === 0) {
                return;
            }


            onClose();

            // Call measureToolsWithList with selected tool numbers and callback
            const machine = Machine.getInstance();
            await (machine.system as any).measureToolsWithList(toolsToMeasure, callback);

        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to measure tools:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to measure tools');
        }
    };

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="sm"
            fullWidth
        >
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: config.primaryColor,
                color: 'white',
                py: 2,
                px: 3
            }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <ToolIcon />
                    Measure Tools
                </Box>
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: 'white',
                        '&:hover': {
                            backgroundColor: 'rgba(255, 255, 255, 0.1)'
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent>
                <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 3 }}>
                    <Typography variant="body1">
                        Confirm tools to measure. All ATC slots with assigned tools are listed below.
                    </Typography>

                    <FormControl fullWidth>
                        <InputLabel>Current Tool in Spindle</InputLabel>
                        <Select
                            value={currentToolNumber ?? ''}
                            onChange={(e) => setCurrentToolNumber(e.target.value === '' ? null : Number(e.target.value))}
                            label="Current Tool in Spindle"
                        >
                            <MenuItem value="">No Tool</MenuItem>
                            {toolLibrary.tools
                                .filter(tool => tool.toolNumber !== null)
                                .sort((a, b) => (a.toolNumber ?? 0) - (b.toolNumber ?? 0))
                                .map((tool) => (
                                    <MenuItem key={tool.toolNumber} value={tool.toolNumber!}>
                                        T{tool.toolNumber} - {tool.displayName}
                                    </MenuItem>
                                ))}
                        </Select>
                    </FormControl>

                    {atcToolsWithNumbers.length === 0 ? (
                        <Typography variant="body2" color="text.secondary">
                            No ATC slots have assigned tool numbers.
                        </Typography>
                    ) : (
                        <>
                            <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
                                <Button
                                    size="small"
                                    onClick={handleSelectAll}
                                    disabled={selectedTools.size === atcToolsWithNumbers.length}
                                >
                                    Select All
                                </Button>
                                <Button
                                    size="small"
                                    onClick={handleDeselectAll}
                                    disabled={selectedTools.size === 0}
                                >
                                    Deselect All
                                </Button>
                            </Box>

                            <Box
                                sx={{
                                    backgroundColor: config.lightBackgroundColor,
                                    borderRadius: 1,
                                    padding: 2,
                                    border: `1px solid ${config.borderColor}`,
                                    maxHeight: '300px',
                                    overflowY: 'auto'
                                }}
                            >
                                {atcToolsWithNumbers.map((toolInfo) => (
                                    <FormControlLabel
                                        key={toolInfo.toolNumber}
                                        control={
                                            <Checkbox
                                                checked={selectedTools.has(toolInfo.toolNumber)}
                                                onChange={() => handleToggleTool(toolInfo.toolNumber)}
                                                sx={{
                                                    color: config.primaryColor,
                                                    '&.Mui-checked': {
                                                        color: config.primaryColor
                                                    }
                                                }}
                                            />
                                        }
                                        label={`T${toolInfo.toolNumber} - ${toolInfo.toolName} (Slot ${toolInfo.clampNumber})`}
                                        sx={{ display: 'block', mb: 0.5 }}
                                    />
                                ))}
                            </Box>
                        </>
                    )}
                </Box>
            </DialogContent>

            <DialogActions sx={{
                p: 2,
                gap: 1,
                justifyContent: 'flex-end',
                borderTop: `1px solid ${config.borderColor}`
            }}>
                <Button
                    onClick={onClose}
                    variant="outlined"
                >
                    Cancel
                </Button>
                <Button
                    onClick={handleMeasure}
                    variant="contained"
                    disabled={selectedTools.size === 0}
                    startIcon={<ToolIcon />}
                    sx={{
                        backgroundColor: config.primaryColor,
                        '&:hover': {
                            backgroundColor: config.primaryColor,
                            filter: 'brightness(0.9)'
                        }
                    }}
                >
                    Measure {selectedTools.size} Tool{selectedTools.size !== 1 ? 's' : ''}
                </Button>
            </DialogActions>
        </Dialog>
    );
}
